        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue
        if (nx, ny) in obstacles:
            continue

        val = 0
        if (nx, ny) in unclaimed:
            val += 1000 if not behind else 900
        if resources:
            dres = min(abs(nx - rx) + abs(ny - ry) for (rx, ry) in resources)
            val += (200 - dres) if not behind else (180 - dres)
